object Main {
  def main(args: Array[String]): Unit = {
    val n = scala.io.StdIn.readInt()
    val nilai = scala.io.StdIn.readLine().trim.split("\\s+").map(_.toInt).toList
    def rentang(x: Int): String = if (x >= 85) "A" else if (x >= 70) "B" else if (x >= 60) "C" else ""
    val hitung = nilai.groupBy(rentang).view.mapValues(_.size).toMap
    val baris = Seq("A", "B", "C").flatMap(k => hitung.get(k).map(c => (k, c)))
    val urut = baris.sortBy(r => (-r._2, r._1))
    if (urut.isEmpty) println("TIDAK ADA")
    else println(urut.map(r => s"${r._1} ${r._2}").mkString(" "))
  }
}

