object Main {
  def main(args: Array[String]): Unit = {
    val nk = scala.io.StdIn.readLine().trim.split("\\s+")
    val n = nk(0).toInt
    val k = nk(1).toInt
    val strings = (1 to n).map(_ => scala.io.StdIn.readLine())
    val bersih = strings.map(s => s.toLowerCase.filter(c => c >= 'a' && c <= 'z'))
    val pal = bersih.filter(s => s.length >= 3 && s == s.reverse).distinct
    val urut = pal.sortBy(s => (-s.length, s)).take(k)
    if (urut.isEmpty) println("TIDAK ADA") else println(urut.mkString(" "))
  }
}
